fetch("./distributions/files.json")
.then(response => response.json())
.then(data => {
    createLatestDataset(data);
    createArchivedDatasets(data);
  })
.catch(error => console.log(error));

var latestDatasetTable = document.getElementById("latestDataset");
function createLatestDataset(data){
    let year = data.latest.year;
    for(let file of data.latest.files){
        let row = createFileRow(file, year);
        latestDatasetTable.appendChild(row);
    }
}
var archivedContainer = document.getElementById("archivedDatasets");
function createArchivedDatasets(data){
    var fragment = document.createDocumentFragment();
    let header = document.createElement("div");
    header.className = "table_header";
    header.innerHTML = `<p>Archived Datasets <i class="far fa-file-archive"></i></p>`;
    fragment.appendChild(header);
    data.distributions.sort(function(a, b){return +b.year - +a.year});

    for(let distribution of data.distributions){
        let year = distribution.year;
        let button = document.createElement("button");
        button.onclick = (event => toggleCollapsible(event));
        button.className = "collapsible";
        button.innerHTML = `${year}<i class="fas fa-plus-square"></i>`;
        let container = document.createElement("div");
        container.className = "collapsible-content";
        let table = document.createElement("table");
        table.className = "dataset-table";
        table.innerHTML = `<tr><th>File</th><th>Date</th><th></th></tr>`;
        let headerRow = document.createElement("tr");
        headerRow.innerHTML = `<tr><th>File</th><th>Date</th> <th></th></tr>`;

        for(let file of distribution.files){
            let row = createFileRow(file, year);
            table.appendChild(row);
        }
        container.appendChild(table);
        fragment.appendChild(button);
        fragment.appendChild(container);
    }
    archivedContainer.innerHTML = "";
    archivedContainer.appendChild(fragment);
}
function createFileRow(file, year){
    let yyyy, mm, dd;
    let split = file.split("_");
    let date = split[1];

    if((file.includes(".zip") || file.includes(".upd") || file.includes(".all")) && file[0] !== "A" && date){
        yyyy = `20${file,date.substring(0, 2)}`;
        mm = date.substring(2, 4);
        dd = date.substring(4, 6);
        mm = Number.isInteger(Number(mm)) ? mm : undefined;
        dd = Number.isInteger(Number(dd)) ? dd : undefined;
    }else{
        yyyy = year;
    }

    let path = `distributions/dist${year.substring(2)}/${file}`;
    let row = document.createElement("tr");
    row.innerHTML = `<td>${file}</td><td>${yyyy}${mm ? `/${mm}${dd ? `/${dd}` : ""}` : ""}</td><td class=download-button><a download="" target="_blank" href="${path}"><i class="fas fa-download"></i><p>Download</p></a></td>`;
    return row;
}

function toggleCollapsible(event){
    let button = event.target.firstElementChild,
        buttonClass = "fas fa-minus-square";
        expandable = event.target.nextElementSibling;
    if(expandable.style.maxHeight == "" || expandable.style.maxHeight == "0px"){
        expandable.style.maxHeight = `${expandable.scrollHeight}px`;
        event.target.classList = "collapsible active";
    }else{
        expandable.style.maxHeight = "0px";
        buttonClass = buttonClass.replace("minus","plus");
        event.target.classList = "collapsible";
    }
    button.classList = buttonClass;
}
